#!/usr/bin/env bash
# Writes evidence/connection.yaml (git-ignored) from the Postgres credentials in .env.
# Evidence's direct Postgres connector queries listmonk live; nothing is synced anywhere.
set -euo pipefail
cd "$(dirname "$0")/.."
. scripts/lib.sh; load_env .env
: "${LISTMONK_PG_HOST:?}" "${LISTMONK_PORT:?}" "${LISTMONK_USER:?}" "${LISTMONK_DATABASE:?}" "${LISTMONK_PGPASSWORD:?}"
SSLMODE="${EVIDENCE_PG_SSLMODE:-require}"
umask 077
cat > evidence/connection.yaml <<YAML
# Generated by scripts/evidence_connection.sh from .env. Do not commit (git-ignored).
type: postgres
host: "${LISTMONK_PG_HOST}"
port: ${LISTMONK_PORT}
user: "${LISTMONK_USER}"
password: "${LISTMONK_PGPASSWORD}"
database: "${LISTMONK_DATABASE}"
sslmode: ${SSLMODE}
schema: public
YAML
echo "wrote evidence/connection.yaml (sslmode=${SSLMODE})"
